PRAGMA foreign_keys=ON;
CREATE TABLE alumnos (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, email TEXT NOT NULL UNIQUE, telefono TEXT);
CREATE TABLE cursos (id INTEGER PRIMARY KEY AUTOINCREMENT, titulo TEXT NOT NULL UNIQUE, nivel TEXT NOT NULL CHECK (nivel IN ('BASICO','MEDIO','AVANZADO')), horas INTEGER NOT NULL CHECK (horas > 0), precio NUMERIC NOT NULL CHECK (precio >= 0));
CREATE TABLE matriculas (id INTEGER PRIMARY KEY AUTOINCREMENT, id_alumno INTEGER NOT NULL REFERENCES alumnos(id), id_curso INTEGER NOT NULL REFERENCES cursos(id), fecha TEXT NOT NULL, importe NUMERIC NOT NULL CHECK (importe >= 0), UNIQUE (id_alumno, id_curso));
